"""Voicemail detector extracted from the authorized original guard_core.py.

Behavior preserved; comments and company-specific incident references omitted.
See docs/PROVENANCE.md.
"""

import re

_VOICEMAIL_RE = re.compile(
    "leave\\s*(?:a|your)\\s*(?:voice\\s*)?message|after\\s*the\\s*(?:tone|beep)|(?:available\\s*)?at\\s*the\\s*(?:tone|beep)|voice\\s*mail|mailbox|record\\s*your\\s*(?:name|message)|state\\s*your\\s*name|reason\\s*for\\s*(?:your\\s*)?call|see\\s*if\\s*(?:this|the)\\s*person\\s*is\\s*available|call\\s*(?:screening|assist)|(?:person|number|subscriber)\\s*you\\s*(?:are|have|'re)\\s*(?:calling|called|dialled|dialed|trying\\s*to\\s*reach)|(?:number|person|subscriber|customer)[^.!?]{0,40}\\b(?:is|are)\\s*(?:currently\\s*)?(?:not\\s*(?:available|reachable)|switched\\s*off|out\\s*of\\s*(?:coverage|reach))|check\\s*the\\s*number\\s*you\\s*have\\s*dial|number\\s*you\\s*have\\s*dial|dial(?:l)?ed\\s*number|संदेश\\s*छोड़|वॉइस\\s*मेल|आपके\\s*द्वारा\\s*डायल|डायल\\s*किया\\s*हुआ\\s*नंबर|(?:नंबर|व्यक्ति|ग्राहक)[^.।!?]{0,30}(?:उपलब्ध\\s*नहीं|स्विच\\s*ऑफ|पहुँच\\s*से\\s*बाहर|व्यस्त)|नंबर\\s*(?:की\\s*)?(?:जाँच|जांच|चांच|चाँच)|दोबारा\\s*कोशिश\\s*करें|कृपया\\s*प्रतीक्षा|अपना\\s*नाम\\s*और\\s*कॉल\\s*करने|पर्सन\\s*इ[सज]\\s*अवेलेबल|पुनः\\s*(?:कोशिश|प्रयास)|नॉट\\s*अवेलेबल|इज़?\\s*नॉट\\s*रीचेबल|रिकॉर्ड\\s*योर\\s*(?:नेम|मैसेज)|लीव\\s*अ\\s*मैसेज|वॉइसमेल|आफ्टर\\s*द\\s*टोन|एट\\s*द\\s*टोन|फिनिश्ड?\\s*रिकॉर्डिंग|हैंग\\s*अप|करंटली\\s*बिजी|ट्राई\\s*(?:अगेन\\s*)?लेटर|कृपया\\s*(?:कुछ\\s*|थोड़ी\\s*)?(?:समय|देर|वक्त)\\s*(?:पश्चात्?|बाद)\\s*(?:पुनः\\s*)?(?:प्रयास|कोशिश)|कृपया\\s*होल्ड|(?:जिस|जस)\\s*व्यक्ति\\s*को\\s*(?:आप\\s*)?कॉल|कॉल\\s*(?:अग्रेषित|फॉरवर्ड)|(?:बीप|टोन)\\s*के\\s*(?:बाद|पश्चात)|संदेश\\s*रिकॉर्ड|रूट\\s*की\\s*सभी\\s*लाइन|all\\s*(?:the\\s*)?lines[^.!?]{0,30}busy|please\\s*(?:stay|hold|wait)\\s*(?:on\\s*the\\s*line|while)|(?:please\\s*)?try\\s*(?:your\\s*call\\s*)?again\\s*(?:later|after)|(?:at|after)\\s*the\\s*(?:tone|beep)[^.!?]{0,30}record|(?:क्रमांक|नंबर)[^.।!?]{0,40}(?:व्यस्त\\s*आहे|उपलब्ध\\s*नाही|पोहोच(?:ण्याच्या)?\\s*(?:क्षेत्राबाहेर|बाहेर)|बंद\\s*आहे)|(?:कृपया\\s*)?(?:थोड्या|काही)\\s*(?:वेळाने|वेळानंतर)\\s*(?:पुन्हा\\s*)?(?:प्रयत्न|संपर्क)|डायल\\s*केलेला|(?:आपण|तुम्ही)\\s*(?:कॉल|संपर्क)\\s*(?:केलेली|करत\\s*असलेली)|संदेश\\s*रेकॉर्ड\\s*करा|தற்போது\\s*(?:பிஸி|தொடர்பு|கிடைக்க)|(?:சிறிது|கொஞ்ச)\\s*நேரம்\\s*கழித்து|முயற்சிக்கவும்|தொடர்பு\\s*எல்லைக்கு|தயவு\\s*செய்து[^.!?]{0,30}(?:முயற்சி|காத்திரு)|நீங்கள்\\s*(?:அழைத்த|டயல்\\s*செய்த)|ದಯವಿಟ್ಟು[^.!?]{0,30}(?:ನಂತರ|ಪ್ರಯತ್ನಿಸಿ)|ನೀವು\\s*(?:ಕರೆ\\s*ಮಾಡಿದ|ಡಯಲ್\\s*ಮಾಡಿದ)|దయచేసి[^.!?]{0,30}(?:తర్వాత|ప్రయత్నించండి)|మీరు\\s*(?:డయల్\\s*చేసిన|కాల్\\s*చేసిన)|(?:number|person|subscriber|customer)\\s*(?:you\\s*(?:are|have|'re)\\s*)?(?:trying\\s*to\\s*(?:call|contact|reach)|calling)[^.!?]{0,40}\\b(?:is|are)\\b|out\\s*of\\s*(?:the\\s*)?(?:network|service)\\s*(?:coverage|area)|(?:is|are)\\s*(?:currently\\s*|temporarily\\s*)?(?:out\\s*of\\s*(?:coverage|reach|range)|not\\s*(?:reachable|answering|responding))|please\\s*try\\s*(?:again\\s*|your\\s*call\\s*)?(?:after\\s*some\\s*time|later\\s*on|after\\s*sometime)|(?:कवरेज|कव्हरेज)\\s*(?:क्षेत्र|एरिया)\\s*(?:से|के)\\s*बाहर|आप[णन]\\s*(?:ज्या|जा|जिस)?\\s*व्यक्ति(?:ला|को)?\\s*कॉल|प्रतीक्षा\\s*करें|प्रतीक\\s*(?:का\\s*)?करें|प्लीज़?\\s*स्टे\\s*ऑन\\s*(?:द\\s*)?लाइन|आई\\s*विल\\s*सी\\s*इफ|is\\s*(?:on\\s*)?another\\s*call|(?:forwarded|forwarding)\\s*to\\s*(?:the\\s*)?(?:voice|an?\\s*automated)|your\\s*call\\s*(?:is|has\\s*been)\\s*(?:being\\s*)?(?:forwarded|recorded|transferred)",
    re.IGNORECASE,
)


def is_voicemail_announcement(text: str) -> bool:
    return bool(_VOICEMAIL_RE.search(text))
